#!/usr/bin/env bash
# fetch_deps.sh — vendor every third-party dependency into third_party/.
#
# One idempotent fetcher for all external deps. Each is pinned to a specific
# release and SHA256-verified, extracted under third_party/, and marked with a
# .vendored-ok stamp so re-running is a no-op ("ignore if exist"). None of the
# fetched trees are committed (see .gitignore); this script replaces the old,
# forgettable manual step — both scripts/build_host.sh and CMake now run it automatically.
#
# Usage:
#   ./third_party/fetch_deps.sh [target ...]
# Targets:
#   libsodium   seal KDF/AEAD source (required for every build)      [default]
#   python      CPython 3.10 stdlib for O-MVLL's embedded interpreter
#   omvll       O-MVLL plugin dylib (+ its bundled matching python)
#   all         libsodium + omvll (omvll also provides python)
# With no target, fetches libsodium only (the sole hard build dependency).
set -euo pipefail
cd "$(dirname "$0")/.."   # repo root

# ---- shared helpers --------------------------------------------------------
# verify_sha256 <file> <expected> — sha256sum/shasum/skip fallback, portable
# across Linux and macOS.
verify_sha256() {
    local file="$1" expected="$2"
    if command -v sha256sum >/dev/null 2>&1; then
        echo "${expected}  ${file}" | sha256sum -c - || {
            echo "ERROR: SHA256 mismatch for $file" >&2; rm -f "$file"; exit 1; }
    elif command -v shasum >/dev/null 2>&1; then
        echo "${expected}  ${file}" | shasum -a 256 -c - || {
            echo "ERROR: SHA256 mismatch for $file" >&2; rm -f "$file"; exit 1; }
    else
        echo "WARN: no sha256sum/shasum found; skipping integrity check for $file" >&2
    fi
}

# ---- libsodium (seal KDF + AEAD) -------------------------------------------
# src/storage/trusted_storage.cpp uses libsodium's Argon2id KDF and
# XChaCha20-Poly1305 AEAD. We build it from a pinned release rather than
# home-rolling crypto. version.h is normally generated by ./configure; the
# release ships a pre-generated copy (identical for our portable build) which we
# drop into the include tree so the source compiles WITHOUT autotools — scripts/build_host.sh
# and CMakeLists.txt just glob the .c files.
SODIUM_VERSION="1.0.20"
SODIUM_SHA256="ebb65ef6ca439333c2bb41a0c1990587288da07f6c7fd07cb3a18cc18d30ce19"
fetch_libsodium() {
    local dest="third_party/libsodium"
    local src="${dest}/libsodium-${SODIUM_VERSION}"
    local stamp="${src}/.vendored-ok"
    if [ -f "$stamp" ]; then
        echo "libsodium ${SODIUM_VERSION} already vendored at ${src}"; return 0
    fi
    mkdir -p "$dest"
    local tarball="${dest}/libsodium-${SODIUM_VERSION}.tar.gz"
    echo "downloading libsodium ${SODIUM_VERSION} ..."
    curl -sSL -o "$tarball" \
        "https://download.libsodium.org/libsodium/releases/libsodium-${SODIUM_VERSION}.tar.gz"
    echo "verifying SHA256 ..."; verify_sha256 "$tarball" "$SODIUM_SHA256"
    echo "extracting ..."; rm -rf "$src"; tar -xzf "$tarball" -C "$dest"
    # Pre-generated version.h from the MSVC build tree (portable build has no
    # -march tuning to configure); drop it into the include tree.
    cp "${src}/builds/msvc/version.h" \
       "${src}/src/libsodium/include/sodium/version.h"
    rm -f "$tarball"; touch "$stamp"
    echo "libsodium ${SODIUM_VERSION} vendored -> ${src}"
}

# ---- CPython 3.10 stdlib (O-MVLL embedded interpreter) ----------------------
# The O-MVLL plugin embeds a CPython VM and aborts ("failed to get the Python
# codec of the filesystem encoding") unless OMVLL_PYTHONPATH points at a 3.10
# stdlib. Only the pure-Python Lib/ is used — no need to build CPython. The
# omvll tarball bundles this exact tree, so fetch_omvll populates it for free;
# this standalone target is the independent python.org path.
PYTHON_VERSION="3.10.7"
PYTHON_SHA256="1b2e4e2df697c52d36731666979e648beeda5941d0f95740aafbf4163e5cc126"
fetch_python() {
    local dest="third_party/python"
    local stamp="${dest}/.vendored-ok"
    if [ -f "$stamp" ]; then
        echo "CPython ${PYTHON_VERSION} already vendored at ${dest}"; return 0
    fi
    mkdir -p third_party
    local tarball="third_party/Python-${PYTHON_VERSION}.tgz"
    echo "downloading CPython ${PYTHON_VERSION} ..."
    curl -sSL -o "$tarball" \
        "https://www.python.org/ftp/python/${PYTHON_VERSION}/Python-${PYTHON_VERSION}.tgz"
    echo "verifying SHA256 ..."; verify_sha256 "$tarball" "$PYTHON_SHA256"
    echo "extracting ..."; rm -rf "$dest"
    tar -xzf "$tarball" -C third_party
    mv "third_party/Python-${PYTHON_VERSION}" "$dest"
    rm -f "$tarball"
    [ -f "${dest}/Lib/abc.py" ] || { echo "ERROR: ${dest}/Lib missing" >&2; exit 1; }
    touch "$stamp"
    echo "CPython ${PYTHON_VERSION} vendored -> ${dest}"
}

# ---- O-MVLL plugin (native-code obfuscator) --------------------------------
# The O-MVLL LLVM pass-plugin, pinned to v1.9.1 / NDK r29 (the config in
# third_party/omvll/omvll_config.py targets this build). Upstream publishes a
# per-host release and they are NOT interchangeable: the plugin is dlopen'd into
# the NDK's clang, so a macOS build needs the Mach-O dylib and a Linux build
# needs the ELF .so. Both tarballs ship a matching Python-3.10.7 stdlib, which we
# reuse for the python dep rather than making a second download; the macOS one is
# larger only because it carries two plugin variants (ndk + xcode) to Linux's one.
#
# omvll_plugin_path — the ONE place the per-host filename is decided. Sourced by
# scripts/build_android.sh too, so the fetcher and the consumer cannot drift onto
# different names (they did not use to be able to disagree; now they could).
omvll_plugin_path() {
    case "$(uname -s)" in
        Darwin) echo "third_party/omvll/omvll_ndk_r29.dylib" ;;
        Linux)  echo "third_party/omvll/omvll_ndk_r29.so" ;;
        *)      echo "third_party/omvll/omvll_ndk_r29.unsupported" ;;
    esac
}

OMVLL_MACOS_SHA256="0471e049b21e7ada4b52bb15bb4bc7d0be67ae385417d9cd78c27e48718470de"
OMVLL_MACOS_URL="https://github.com/open-obfuscator/o-mvll/releases/download/1.9.1/omvll_v1-9-1_macos_2026-07-08T15_08_58.tar.gz"
OMVLL_LINUX_SHA256="f1f8f88812e173ea44d74372502c4a09600810de3254dbae1f82599bfc339aa0"
OMVLL_LINUX_URL="https://github.com/open-obfuscator/o-mvll/releases/download/1.9.1/omvll_v1-9-1_linux_2026-07-06T09_44_15.tar.gz"

fetch_omvll() {
    local dest="third_party/omvll"
    local plugin; plugin="$(omvll_plugin_path)"
    # Per-host stamp. A shared checkout (a git submodule mounted into a Linux
    # container from a macOS working copy, say) has the macOS plugin AND a valid
    # stamp, and a single stamp would report "already vendored" while the .so this
    # host needs is absent. Keying the stamp to the host makes that self-correcting.
    local stamp="${dest}/.vendored-ok-$(uname -s)"
    local url sha member
    case "$(uname -s)" in
        Darwin) url="$OMVLL_MACOS_URL"; sha="$OMVLL_MACOS_SHA256"; member="omvll-ndk.dylib" ;;
        Linux)  url="$OMVLL_LINUX_URL"; sha="$OMVLL_LINUX_SHA256"; member="omvll-ndk.so" ;;
        *) echo "ERROR: no O-MVLL release for $(uname -s); build with --no-omvll" >&2; exit 1 ;;
    esac

    if [ -f "$stamp" ] && [ -f "$plugin" ]; then
        echo "O-MVLL plugin already vendored at ${plugin}"
    else
        mkdir -p "$dest"
        local tarball="${dest}/omvll-v1.9.1.tar.gz"
        echo "downloading O-MVLL v1.9.1 plugin ($(uname -s)) ..."
        curl -sSL -o "$tarball" "$url"
        echo "verifying SHA256 ..."; verify_sha256 "$tarball" "$sha"
        local tmp; tmp="$(mktemp -d)"
        echo "extracting ..."; tar -xzf "$tarball" -C "$tmp"
        # Install the NDK plugin under the repo's stable per-host name. Name the
        # tarball's actual contents on a miss: upstream renaming a member is the
        # realistic breakage here, and "not found" alone would send you reading
        # this script instead of the listing that answers it.
        local found; found="$(find "$tmp" -name "$member" -print -quit)"
        if [ -z "$found" ]; then
            echo "ERROR: $member not found in the O-MVLL tarball. It contains:" >&2
            (cd "$tmp" && find . -maxdepth 2 -name 'omvll*' -o -maxdepth 1 -type f) >&2
            rm -rf "$tmp" "$tarball"; exit 1
        fi
        cp "$found" "$plugin"
        # Reuse the bundled, version-matched CPython stdlib for the python dep
        # (avoids a redundant python.org download) unless already vendored.
        if [ ! -f "third_party/python/.vendored-ok" ]; then
            local pysrc; pysrc="$(find "$tmp" -maxdepth 2 -type d -name 'Python-*' -print -quit)"
            if [ -n "$pysrc" ] && [ -f "${pysrc}/Lib/abc.py" ]; then
                echo "installing bundled $(basename "$pysrc") stdlib -> third_party/python"
                rm -rf third_party/python; mv "$pysrc" third_party/python
                touch "third_party/python/.vendored-ok"
            fi
        fi
        rm -rf "$tmp" "$tarball"; touch "$stamp"
        echo "O-MVLL plugin vendored -> ${plugin}"
    fi
    # Guarantee the python dep is present even if the bundle path was skipped.
    fetch_python
    # ...and that it is REAL, not merely stamped. fetch_python short-circuits on
    # third_party/python/.vendored-ok, so a stamp left over an incomplete tree
    # would sail through both branches above and only fail much later, inside the
    # plugin, as "failed to get the Python codec of the filesystem encoding".
    [ -f "third_party/python/Lib/abc.py" ] || {
        echo "ERROR: third_party/python is stamped as vendored but has no Lib/abc.py." >&2
        echo "       The O-MVLL plugin embeds CPython 3.10 and aborts without that stdlib." >&2
        echo "       Fix: rm -rf third_party/python && ./third_party/fetch_deps.sh python" >&2
        exit 1; }
}

# ---- dispatch --------------------------------------------------------------
# Only when EXECUTED. scripts/build_android.sh sources this file to reuse
# omvll_plugin_path (one definition of the per-host plugin filename, rather than
# two that can drift), and a sourced script that fetches libsodium as a side
# effect would be a trap.
if [ "${BASH_SOURCE[0]}" != "$0" ]; then
    return 0
fi

[ "$#" -eq 0 ] && set -- libsodium
for target in "$@"; do
    case "$target" in
        libsodium) fetch_libsodium ;;
        python)    fetch_python ;;
        omvll)     fetch_omvll ;;
        all)       fetch_libsodium; fetch_omvll ;;  # omvll also provides python
        *) echo "unknown target: $target (want: libsodium|python|omvll|all)" >&2; exit 2 ;;
    esac
done
